class SegmentTree:
    def __init__(self, low, high):
        self.low = low
        self.high = high
        self.left = None
        self.right = None
        self.value = 0

    def build(self, low, high):
        if low == high:
            return
        mid = (low + high) // 2
        self.left = SegmentTree(low, mid)
        self.right = SegmentTree(mid + 1, high)
        self.left.build(low, mid)
        self.right.build(mid + 1, high)

    def update(self, idx, val):
        if self.low == self.high:
            self.value += val
            return
