import sys

class SegmentTree:
    def __init__(self, start, end, value=0, left=None, right=None):
        self.start = start
        self.end = end
        self.value = value
        self.left = left
        self.right = right

    @classmethod
    def build(cls, start, end, points):
        if start == end:
            return SegmentTree(start, end, value=1 if start in points else 0)

        mid = (start + end) // 2
        left = cls.build(start, mid, points)
        right = cls.build(mid + 1, end, points)

        return SegmentTree(start, end, value=left.value + right.value, left=left, right=right)

    def query(self, start, end):
        if self.start > end or self.end < start:
            return 0
        if self.start >= start and self.end <= end:
            return self.value

        return self.left.query(start, end) + self.right.query(start, end)

    def update(self, index, value):
        if self.start == self.end:
            self.value = value
            return

        if index <= self.left.end:
            self.left.update(index, value)
        else:
            self.right.update(index, value)

        self.value = self.left.value + self.right.value

