def multiply(a, b):
    """Multiply two integers as strings and return the product as a string."""
    a, b = str(a), str(b)
    res = [0] * (len(a) + len(b))
    for i in range(len(a)-1, -1, -1):
        for j in range(len(b)-1, -1, -1):
            res[i + j + 1] += int(a[i]) * int(b[j])
            res[i + j] += res[i + j + 1] // 10
            res[i + j + 1] %= 10
    start = 0
    while start < len(res) - 1 and res[start] == 0:
        start += 1
    return ''.join(map(str, res[start:])) or '0'

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    ai = list(map(int, input[1:n+1]))

    product = '1'
    has_zero = False
    for num in ai:
        if num == 0:
            has_zero = True
            break
        product = multiply(product, num)

    if has_zero:
        print('0')
    else:
        print(product)

if __name__ == "__main__":
