class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x, root_y = self.find(x), self.find(y)
        if root_x != root_y:
            if self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            elif self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1


def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n, m = int(input[idx]), int(input[idx+1])
    idx += 2
    uf = UnionFind(m + 1)  # 1-based indexing for bulbs

    for _ in range(n):
        xi = int(input[idx])
        idx += 1
        bulbs = list(map(int, input[idx:idx+xi]))
        idx += xi
        for bulb in bulbs:
            uf.union(bulb, bulbs[0])  # Union all bulbs of this button

    root = uf.find(1)
    for i in range(2, m + 1):
        if uf.find(i) != root:
            print("NO")
            return
    print("YES")


if __name__ == "__main__":
    main()

