import sys
import itertools

def overlapping_intervals(intervals):
    """Return the overlapping part of a list of intervals."""
    if not intervals:
        return None
    start = max(i[0] for i in intervals)
    end = min(i[1] for i in intervals)
    if start <= end:
        return (start, end)
    else:
        return None

def main():
    n = int(sys.stdin.readline())
    friends = []
    for _ in range(n):
        parts = sys.stdin.readline().split()
        gender = parts[0][0]
        a, b = map(int, parts[1:])
        friends.append((gender, a, b))

    max_count = 0

    # Iterate over all possible subsets of friends
    for k in range(1, n+1):
        for subset in itertools.combinations(friends, k):
            male_subset = [f for f in subset if f[0] == 'M']
            female_subset = [f for f in subset if f[0] == 'F']

            if len(male_subset) != len(female_subset):
                continue

            male_intervals = [(f[1], f[2]) for f in male_subset]
            female_intervals = [(f[1], f[2]) for f in female_subset]

            male_overlap = overlapping_intervals(male_intervals)
            female_overlap = overlapping_intervals(female_intervals)

            if male_overlap and female_overlap:
                combined_overlap = overlapping_intervals([male_overlap, female_overlap])
                if combined_overlap:
                    max_count = max(max_count, len(male_subset) + len(female_subset))

    print(max_count)

if __name__ == "__main__":
    main()

