def find_overlapping_days(intervals):
    overlapping_days = []
    for start, end in intervals:
        overlapping_days.extend(range(start, end + 1))
    overlapping_days = sorted(set(overlapping_days))
    return overlapping_days

def count_friends_by_day(intervals, overlapping_days):
    day_counts = {day: 0 for day in overlapping_days}
    for start, end in intervals:
        for day in overlapping_days:
            if start <= day <= end:
                day_counts[day] += 1
    return day_counts

