def parse_blocks(blocks):
    parsed = []
    total_length = 0
    for block in blocks:
        length = int(block[0])
        char = block[1]
        parsed.append((char, length))
        total_length += length
    return parsed, total_length

def can_fit(t_block, s_block, t_length, s_length, t_index, s_index):
    if t_block[0] != s_block[0]:
        return False
    remaining_t_length = t_length - sum([x[1] for x in t_block[:t_index]])
    required_s_length = sum([x[1] for x in s_block[:s_index]]) + s_block[s_index][1]
    if required_s_length > remaining_t_length:
        return False
    return True

def find_occurrences(t_blocks, s_blocks, t_length, s_length):
    count = 0
    t_index = 0
    while t_index < len(t_blocks):
        s_index = 0
        fit = True
