class Node:
    def __init__(self):
        self.children = [None]*10
        self.year = None

class Trie:
    def __init__(self):
        self.root = Node()
        self.current_year = 1989

    def add_year(self, year):
        num_str = str(year)
        node = self.root
        for digit in num_str:
            digit = int(digit)
            if node.children[digit] is None:
                node.children[digit] = Node()
            node = node.children[digit]
        node.year = year

    def find_year(self, s):
        node = self.root
        for digit in s:
            digit = int(digit)
            if node.children[digit] is None:
                return None
            node = node.children[digit]
        return node.year

    def generate_years(self):
        while True:
            yield self.current_year
            self.current_year += 1

