def count_syllables(word):
    """Count the minimum possible syllables in a word"""
    if not re.search('[aeiouy]', word):
        return 0
    return len(re.findall('[aeiouy]', word))

def split_syllables(word, target):
    """Try to split a word into a target number of syllables"""
    vowels = [i for i, c in enumerate(word) if c in 'aeiouy']
    if len(vowels) < target:
        return False
    if target == 1:
        return True
    # Greedy approach: place syllable breaks at the latest possible positions
    breaks = [0] * (target - 1)
    for i in range(target - 2, -1, -1):
        breaks[i] = vowels[i+1] - 1
    # Check if all breaks are valid (i.e., not at the start or end of a vowel sequence)
    for i in range(target - 1):
        if breaks[i] == 0 or breaks[i] == len(word) - 1 or (word[breaks[i]] in 'aeiouy' and word[breaks[i]+1] in 'aeiouy'):
            return False
    return True

def match_line(line, target):
    """Check if a line can be split into a target number of syllables"""
    words = line.split()
    syllables = sum(count_syllables(word) for word in words)
    if syllables < target:
        return False
    if syllables == target:
        return True
    # Try to redistribute syllables
    for word in words:
        if count_syllables(word) > 1:
            if split_syllables(word, target - (syllables - count_syllables(word))):
                return True
    return False

