            else:
                supposed[i] = a[i]

    # Second pass: Adjust supposed superiors count based on immediate superiors
    for i in range(n):
        if supposed[i] != -1 and supposed[i] != 0:  # Not chief and not claiming to be chief
            immediate_superior = find_immediate_superior(i, supposed, n)
            if immediate_superior != -1:
                supposed[i] = supposed[immediate_superior] + 1

    # Third pass: Compare reported with supposed, count mistakes
    for i in range(n):
        if supposed[i] != -1 and a[i] != supposed[i]:
            mistakes += 1

    return mistakes

def find_immediate_superior(worker, supposed, n):
    for superior in range(n):
