class Tree:
    def __init__(self, n):
        self.n = n
        self.children = [[] for _ in range(n + 1)]
        self.dist = [0] * (n + 1)
        self.a = [0] * (n + 1)
        self.res = [0] * (n + 1)

    def add_edge(self, u, v, w):
        self.children[u].append((v, w))

