class Reader:
    def __init__(self):
        self.lock = sys.stdin
        selfbuf = ''
        self.pos = 0

    def read(self, num):
        while True:
            if self.pos >= len(selfbuf):
                selfbuf = self.lock.readline()
                self.pos = 0
                if not selfbuf:
                    return []
            res = []
            for _ in range(num):
                if self.pos >= len(selfbuf):
                    break
                res.append(ord(selfbuf[self.pos]))
                self.pos += 1
            if res:
                return res
            else:
                return []

    def readline(self):
        while True:
            if self.pos >= len(selfbuf):
                selfbuf = self.lock.readline()
                self.pos = 0
                if not selfbuf:
                    return ''
            line = selfbuf[self.pos:].split('\n')[0]
            self.pos += len(line) + 1
            return line

    def readInt(self):
        return int(self.readline())

    def readLong(self):
        return int(self.readline())

    def readDouble(self):
        return float(self.readline())

    def readBytes(self, num):
        return self.read(num)

