import sys

def can_form_rectangle(grid):
    """Check if two identical copies of the grid can form a rectangle."""
    n, m = len(grid), len(grid[0])

    # Check if the grid has a hole
    visited = [[False]*m for _ in range(n)]
    holes = 0
    for i in range(n):
        for j in range(m):
            if not visited[i][j] and grid[i][j] == '.':
                holes += 1
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                            visited[nx][ny] = True
                            stack.append((nx, ny))
    if holes > 1:
        return False

    # Check all possible positions to place the second piece
    for dx in range(-n+1, n):
        for dy in range(-m+1, m):
            # Check if the second piece is within bounds and doesn't overlap
            valid = True
            overlap = False
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == 'X':
                        nx, ny = i + dx, j + dy
                        if not (0 <= nx < n and 0 <= ny < m):
                            valid = False
                        elif grid[nx][ny] == 'X':
                            overlap = True
            if valid and not overlap:
                # Check if the combined shape is a solid rectangle
                combined = [[ '.' for _ in range(m)] for _ in range(n)]
                for i in range(n):
                    for j in range(m):
                        if grid[i][j] == 'X':
                            combined[i][j] = 'X'
                            nx, ny = i + dx, j + dy
                            if 0 <= nx < n and 0 <= ny < m:
                                combined[nx][ny] = 'X'
                # Check if the combined shape is a rectangle
                min_x, max_x = n-1, 0
                min_y, max_y = m-1, 0
                for i in range(n):
                    for j in range(m):
                        if combined[i][j] == 'X':
                            min_x, max_x = min(min_x, i), max(max_x, i)
                            min_y, max_y = min(min_y, j), max(max_y, j)
                for i in range(min_x, max_x+1):
                    for j in range(min_y, max_y+1):
                        if combined[i][j] != 'X':
                            valid = False
                if valid:
                    return True
    return False

def main():
    """Read input and output the result."""
