import sys

class Solution:
    def __init__(self, n, m, grid):
        self.n = n
        self.m = m
        self.grid = grid

    def is_valid(self, x, y):
        return 0 <= x < self.n and 0 <= y < self.m

    def get_shape(self):
        shape = set()
        for i in range(self.n):
            for j in range(self.m):
                if self.grid[i][j] == 'X':
                    shape.add((i, j))
        return shape

    def try_place(self, shape1, shape2, dx, dy):
        for (x, y) in shape1:
            if not self.is_valid(x + dx, y + dy) or (x + dx, y + dy) in shape2:
                return False
        return True

    def solve(self):
        shape = self.get_shape()
        if len(shape) % 2 != 0:
            return "NO"
        for dx in range(-self.n + 1, self.n):
            for dy in range(-self.m + 1, self.m):
                if dx == 0 and dy == 0:
                    continue
                shape2 = {(x + dx, y + dy) for (x, y) in shape}
                if shape2 & shape:
                    continue
                if self.try_place(shape, shape2, dx, dy) and self.try_place(shape2, shape, -dx, -dy):
                    combined = shape | shape2
                    min_x = min(x for x, y in combined)
                    max_x = max(x for x, y in combined)
                    min_y = min(y for x, y in combined)
                    max_y = max(y for x, y in combined)
                    if (max_x - min_x + 1) * (max_y - min_y + 1) == len(combined):
                        return "YES"
        return "NO"

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(n)]
    sol = Solution(n, m, grid)
    print(sol.solve())

if __name__ == "__main__":
    main()

