from collections import deque

def bfs(grid, p_positions, w_positions, visited):
    q = deque([w_positions])
    while q:
        current = q.popleft()
        for x, y in current:
            for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 'P' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    q.append([(nx, ny)])
    return len(visited)

