import sys

def count_divisors(n):
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if n // i == i:
                count += 1
            else:
                count += 2
    return count

def smallest_number_with_n_divisors(n):
    i = 1
    while True:
        if count_divisors(i) == n:
            return i
        i += 1

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def smallest_number_with_n_divisors_optimized(n):
    if n == 1:
        return 1

    factors = prime_factors(n)
    factors.sort(reverse=True)

    # Generate exponents
    exponents = [1] * len(factors)
    idx = 0
    while True:
        num = 1
        for i in range(len(factors)):
            num *= (factors[i] ** exponents[i])
        if count_divisors(num) == n:
            return num

        # Increment exponents
        exponents[idx] += 1
        if exponents[idx] > factors[idx]:
            exponents[idx] = 1
            idx += 1
            if idx == len(factors):
                break
        else:
            idx = 0

