def calculate_f(x):
    """Calculates f(x) based on the given recurrence relation."""
    result = 0
    while x > 0:
        result += x & 1
        x >>= 1
    return result

def count_pairs_with_equal_f(a):
    """Counts pairs of indexes (i, j) where i < j and f(a[i]) == f(a[j])."""
    f_values = {}
    for num in a:
        f_val = calculate_f(num)
        if f_val in f_values:
            f_values[f_val] += 1
        else:
            f_values[f_val] = 1

    pairs_count = 0
    for count in f_values.values():
        # Calculate combinations of 2 from 'count' elements
        pairs_count += count * (count - 1) // 2

    return pairs_count

