import sys

class Sequence:
    def __init__(self):
        self.seq = [0]
        self.total = 0
        self.size = 1

    def add(self, ai, xi):
        ai = min(ai, self.size)
        self.total += ai * xi
        for i in range(ai):
            self.seq[i] += xi

    def append(self, ki):
        self.seq.append(ki)
        self.total += ki
        self.size += 1

    def remove(self):
        self.total -= self.seq.pop()
        self.size -= 1

    def average(self):
        return self.total / self.size

def main():
    n = int(sys.stdin.readline())
    seq = Sequence()
    for _ in range(n):
        args = list(map(int, sys.stdin.readline().split()))
        t = args[0]
        if t == 1:
            ai, xi = args[1], args[2]
            seq.add(ai, xi)
        elif t == 2:
            ki = args[1]
            seq.append(ki)
        else:
            seq.remove()
        print("{0:.6f}".format(seq.average()))

if __name__ == "__main__":
