import sys
from collections import defaultdict, deque

class Graph:
    def __init__(self):
        self.graph = defaultdict(list)

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def find_start(self):
        degrees = {city: len(neighbors) for city, neighbors in self.graph.items()}
        for city, degree in degrees.items():
            if degree == 1:
                return city
        return None

    def dfs(self, start):
        visited = set()
        path = []
        stack = deque([start])

        while stack:
            city = stack.pop()
            if city not in visited:
                visited.add(city)
                path.append(city)
                for neighbor in self.graph[city]:
                    if neighbor not in visited:
                        stack.append(neighbor)

        return path

def main():
    n = int(sys.stdin.readline())
    graph = Graph()

    for _ in range(n):
        u, v = map(int, sys.stdin.readline().split())
        graph.add_edge(u, v)

    start = graph.find_start()
    path = graph.dfs(start)

    print(' '.join(map(str, path)))

if __name__ == '__main__':
    main()

