def can_obtain_distinct_array(n, array):
    """
    Checks if it's possible to obtain an array where any two neighboring elements are distinct.
    """
    # Create a frequency dictionary to count occurrences of each number
    freq = {}
    for num in array:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Check if any number appears more than half of the array length + 1
    for count in freq.values():
        if count > (n + 1) // 2:
            return False

    return True


