def get_input_words():
    """Read six words from standard input."""
    return [sys.stdin.readline().strip() for _ in range(6)]

def generate_possible/configurations(words):
    """Generate all permutations of words and their possible configurations."""
    # Permute words to try all orders
    permutations = list(itertools.permutations(words))

    configurations = []
    for perm in permutations:
        # Attempt to create a configuration for this permutation
        config = try_create_config(perm)
        if config:
            configurations.append(config)
    return configurations

def try_create_config(words):
    """Attempt to create a crossword configuration from the given word order."""
    # Assign words to positions (horizontal/vertical)
    h1, h2, v1, v2, h3, v3 = words

    # Basic checks based on problem constraints
    if len(h1) != len(v1) + 1 or len(h2) != len(v2) + 1 or len(h3) != len(v3) + 1:
        return None

    # Initialize the grid with dots
    size_h1 = len(h1)
    size_v3 = len(v3)
    grid = [['.' for _ in range(size_h1)] for _ in range(size_v3)]

    # Place horizontal words
    for i, c in enumerate(h1):
        grid[0][i] = c
    for i, c in enumerate(h2):
        grid[-1][i] = c
    for i, c in enumerate(h3):
        grid[len(v1)][i] = c

    # Place vertical words
    for i, c in enumerate(v1):
        grid[i][0] = c
    for i, c in enumerate(v2):
        grid[i][-1] = c
    for i, c in enumerate(v3):
        grid[i][len(h1)-1] = c

    # Check for overlaps and consistency
    if not check_grid_consistency(grid):
        return None

    return grid

def check_grid_consistency(grid):
    """Verify the grid for any inconsistencies (overlapping letters, incorrect sizes)."""
    # Check each cell for consistency (either a dot or matching both horizontal and vertical words)
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != '.':
                # If it's not a dot, it must match both the horizontal and vertical word at this position
                h_word = None
                v_word = None
                if i == 0:
                    h_word = h1
                elif i == len(grid) - 1:
                    h_word = h2
                elif i == len(v1):
                    h_word = h3

                if j == 0:
                    v_word = v1
                elif j == len(grid[0]) - 1:
                    v_word = v2
                else:
                    v_word = v3

                if (h_word and j < len(h_word) and h_word[j] != grid[i][j]) or \
                   (v_word and i < len(v_word) and v_word[i] != grid[i][j]):
                       return False
    return True

def find_lexicographically_smallest(configurations):
    """Find the lexicographically smallest configuration among the valid ones."""
    if not configurations:
        return None
    # Convert grids to strings for easy comparison, then find the smallest
    config_strings = ['\n'.join([''.join(row) for row in config]) for config in configurations]
    smallest_config_string = min(config_strings)
    return smallest_config_string.split('\n')

