from itertools import permutations

def crossword(words):
    # Generate all permutations of words
    perms = permutations(words)

    for perm in perms:
        # Assign words to positions
        top, right, bottom, left, diag1, diag2 = perm

        # Calculate grid dimensions
        rows = len(top) + len(bottom)
        cols = len(left) + len(right)

        # Initialize grid with dots
        grid = [['.' for _ in range(cols)] for _ in range(rows)]

        # Fill in the words
        for i, c in enumerate(top):
            grid[i][i] = c
        for i, c in enumerate(right):
            grid[len(top) - 1 + i][len(left) - 1 + i] = c
        for i, c in enumerate(bottom):
            grid[len(top) + len(right) - 1 - i][len(left) + len(right) - 1 - i] = c
        for i, c in enumerate(left):
            grid[i + len(top)][i] = c
        for i, c in enumerate(diag1):
            grid[len(top) - 1 - i][len(left) - 1 + i] = c
        for i, c in enumerate(diag2):
            grid[len(top) + i][len(left) + len(right) - 1 - i] = c

        # Check for conflicts
        valid = True
        for row in grid:
            for cell in row:
                if cell == '.':
                    continue
                if not 'A' <= cell <= 'Z':
                    valid = False
                    break
            if not valid:
                break

        if valid:
            # Check for empty spaces
            empty_spaces = 0
            for row in grid:
                for cell in row:
                    if cell == '.':
                        empty_spaces += 1
            if empty_spaces == 4 * len(words) - 12:  # 4 blanks for 6 words
                return '\n'.join(''.join(row) for row in grid)

    return "Impossible"

