def find_valid_sequence(dates):
    """Use backtracking to find a valid sequence of dates."""
    n = len(dates)
    prev_date = 1000
    result = []

    def backtrack(index, path):
        nonlocal result
        if index == n:
            result = path[:]
            return
        if len(path) > 0:
            prev_date = path[-1]
        else:
