def solve_crossword(n, m, grid):
    # Create sets to track unique letters in rows and columns
    row_sets = [set(row) for row in grid]
    col_sets = [set() for _ in range(m)]

    for i in range(n):
        for j in range(m):
            col_sets[j].add(grid[i][j])

    # Identify letters to keep (appear only once in row and column)
    keep = [[ch for ch in row if list(row).count(ch) == 1 and list(grid[i]).count(ch) == 1] for i, row in enumerate(grid)]

    # Join kept letters row-wise and then column-wise (as per problem's 'higher position' rule)
    result = []
    for col_idx in range(m):
        for row_idx in range(n):
            if keep[row_idx][col_idx]:
                result.append(keep[row_idx][col_idx])

    return ''.join(result)

