def solve_crossword(n, m, grid):
    """
    Solve an African Crossword by removing repeated letters in rows and columns.

    :param n: Number of rows in the grid
    :param m: Number of columns in the grid
    :param grid: 2D list representing the crossword grid
    :return: The decoded word as a string
    """
    # Create a set to store the positions of letters to be crossed out
    cross_out = set()

    # Iterate over each row to find repeated letters
    for i in range(n):
        row_counts = {}
        for j in range(m):
            letter = grid[i][j]
            row_counts[letter] = row_counts.get(letter, 0) + 1
            if row_counts[letter] > 1:
                cross_out.add((i, j))

    # Iterate over each column to find repeated letters
    for j in range(m):
        col_counts = {}
        for i in range(n):
            letter = grid[i][j]
            col_counts[letter] = col_counts.get(letter, 0) + 1
            if col_counts[letter] > 1:
                cross_out.add((i, j))

    # Build the result string by iterating over the grid and skipping crossed out letters
    result = []
    for i in range(n):
        for j in range(m):
            if (i, j) not in cross_out:
