def count_selections(n, m, a, b):
    """
    Calculate the minimum number of selections required to select folders from a to b.

    :param n: Total number of folders
    :param m: Width of the window
    :param a: First folder to delete (inclusive)
    :param b: Last folder to delete (inclusive)
    :return: Minimum number of selections
    """
    def row(col):
        return (col - 1) // m + 1

    def col(row):
        return (row - 1) * m + 1

    selections = 0

    # Check if the range spans across rows
    if row(a) != row(b):
        # Select the rest of the first row
        if a <= m * row(a):
            selections += 1
        # Select full rows in between
        if row(a) + 1 <= row(b) - 1:
            selections += 1
        # Select the start of the last row
        if b >= col(row(b)):
            selections += 1
    else:
        # All folders are in the same row
        if a == 1 and b == n:
            selections = 1
        elif a == 1:
            selections = 1
        elif b == n:
            selections = 1
        else:
            selections = 2

    # Edge case: when only one folder needs to be selected
    if a == b:
        selections = 1

    return selections

