from itertools import permutations

def rot(xyz, loc):
    a, b, c = xyz
    if loc == 0: return (a, b, c)
    if loc == 1: return (b, c, a)
    if loc == 2: return (c, a, b)
    if loc == 3: return (a, c, b)
    if loc == 4: return (c, b, a)
    if loc == 5: return (b, a, c)

def canonize(p):
    mins = []
    for i in range(6):
        xyz = rot(p[0], i)
        for j in range(4):
            for k in range(4):
                for l in range(4):
                    mins.append(tuple(rot(xyz, l) + rot(p[1], j) + rot(p[2], k) + rot(p[3], j) + rot(p[4], l) + rot(p[5], k)))
    return min(mins)

def solve(s):
    s = list(s)
    perms = set()
    for p in permutations(s):
        perms.add(canonize(p))
    return len(perms)

