from itertools import permutations

def rotate_clockwise(cube):
    return [cube[1], cube[2], cube[5], cube[0], cube[3], cube[4]]

def rotate_counter_clockwise(cube):
    return [cube[2], cube[1], cube[0], cube[5], cube[3], cube[4]]

def rotate(cube, times):
    for _ in range(times):
        cube = rotate_clockwise(cube)
    return cube

def rotate_face(cube, face, direction):
    if face == 0:
        if direction == 1:
            return rotate_clockwise(cube)
        else:
            return rotate_counter_clockwise(cube)
    elif face == 1:
        if direction == 1:
            return rotate(cube, 1)
