import sys
from collections import deque

def calculate_operations(deck):
    operations = 0
    min_val = min(deck)
    queue = deque(deck)
    while queue:
        current = queue.popleft()
        operations += 1
        if current == min_val:
            min_val = min(queue) if queue else float('inf')
        else:
            queue.append(current)
    return operations

def main():
    n = int(sys.stdin.readline())
    deck = list(map(int, sys.stdin.readline().split()))
    print(calculate_operations(deck))

if __name__ == "__main__":
    main()

