from collections import defaultdict, deque

class Graph:
    def __init__(self, n):
        self.n = n
        self(adj) = defaultdict(list)

    def add_edge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

def bfs(graph, start):
    dist = [0] * (graph.n + 1)
    visited = [False] * (graph.n + 1)
    queue = deque([start])
    visited[start] = True

    while queue:
        u = queue.popleft()
        for v in graph.adj[u]:
            if not visited[v]:
                visited[v] = True
                dist[v] = dist[u] + 1
                queue.append(v)

    return dist

